import sys
import time
from collections import defaultdict

def parse_spec_file(file_path):
    names = {}
    with open(file_path, 'r') as file:
        for line in file:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            parts = stripped.split('=', 1)
            if len(parts) != 2:
                continue
            name, expr = parts
            if not name.isidentifier():
                continue
            names[name] = expr
    return names

def evaluate_expression(expr, variables):
    try:
        # Replace variable names with their values
        for name in variables:
            expr = expr.replace(name, str(variables[name]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, variables)
    except:
        return None

def process_spec_file(file_path, max_per_second):
    names = {}
    output_lines = []
    last_print_time = time.time()
    print_count = 0

    with open(file_path, 'r') as file:
        for line in file:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            parts = stripped.split('=', 1)
            if len(parts) != 2:
                continue
            name, expr = parts
            if not name.isidentifier():
                continue

            # Evaluate the expression
            result = evaluate_expression(expr, names)
            if result is None:
                output_lines.append(f"{name}: error")
                continue

            # Store the result
            names[name] = result

            # Prepare output line
            output_line = f"{name}: {result}"
            output_lines.append(output_line)

            # Check print rate
            current_time = time.time()
            if current_time - last_print_time >= 1:
                if print_count >= max_per_second:
                    time.sleep(1 - (current_time - last_print_time))
                    current_time = time.time()
                    print_count = 0
                print('\n'.join(output_lines), end='')
                output_lines = []
                print_count += 1
                last_print_time = current_time
            else:
                print_count += 1

if __name__ == "__main__":
