    spec_file = sys.argv[1]
    max_per_second = int(sys.argv[2])

    try:
        with open(spec_file, 'r') as f:
            lines = f.read().split('\n')
    except IOError:
        sys.exit(1)

    names = {}
    output_lines = []
    last_print_time = time.time()

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        if '=' not in stripped:
            continue

        name_part, expr_part = stripped.split('=', 1)
        name = name_part.strip()
        expr = expr_part.strip()

        if not name.isidentifier() or not name[0].isalpha():
            continue

        value = parse_expression(expr)
        if value is None:
            print(f"{name}: error")
            continue

        names[name] = value
        output_lines.append((name, value))

    # Process output with rate limiting
    for name, value in output_lines:
        current_time = time.time()
        elapsed = current_time - last_print_time
        if elapsed < 1.0 / max_per_second:
            time.sleep(1.0 / max_per_second - elapsed)
            current_time = time.time()

        print(f"{name}: {value}")
        last_print_time = current_time

